const input = $input.first().json.body;

const locale = input.locale || 'fr';
const LANG_MAP = {
  en:'English', fr:'French', es:'Spanish', ar:'Arabic',
  pt:'Portuguese', de:'German', it:'Italian', nl:'Dutch', tr:'Turkish'
};
const language = LANG_MAP[locale] || 'French';

const aiConfig    = input.ai_config || {};
const nbQuestions = Math.max(1, Math.min(10, parseInt(aiConfig.numberOfQuestions) || 3));
const complexity  = aiConfig.questionComplexity || 'intermediate';
const tone        = aiConfig.tone || 'professional';
const extraCtx    = aiConfig.questionContext || '';

const agent = input.active_agent || null;
const agentActive = !!(agent?.name);
let persona;
if (agentActive && agent.base_prompt) {
  persona = agent.base_prompt + (agent.description ? '\n(Agent context: ' + agent.description + ')' : '');
} else if (agentActive) {
  persona = 'Agent: ' + agent.name + (agent.description ? '. ' + agent.description : '');
} else if (aiConfig.systemPrompt) {
  persona = aiConfig.systemPrompt;
} else {
  persona = 'You are an expert lead qualification consultant. Your role is to ask targeted follow-up questions that uncover the prospect\'s real needs, context, budget signals, and readiness to act.';
}

const staticAnswers = input.static_answers || {};
const answersBlock = Object.entries(staticAnswers)
  .map(([k, v]) => '- ' + k + ': ' + String(v))
  .join('\n') || '(No answers provided yet)';

const formTitle = (input.form_title || 'Qualification form').replace(/"/g, '\\"');

const prompt =
`<s>
You are an elite prospect qualification AI. Your mission: generate precise, high-value follow-up questions based strictly on the prospect's existing answers.
Every question you generate must deepen qualification — uncovering need depth, budget signals, urgency, timeline, or decision authority.
Reason internally before generating. Then output ONLY the JSON.
</s>

<persona>
${persona}
</persona>

<output_language>
ALL user-visible text (labels, placeholders, options) MUST be written in ${language}.
Instructions and reasoning are in English.
</output_language>

<rules>
1. Generate EXACTLY ${nbQuestions} questions — not one more, not one less.
2. Every question MUST be a direct logical follow-up to the existing answers — zero generic questions.
3. Qualification priorities in order: need depth → budget signal → urgency/timeline → decision authority.
4. Complexity: ${complexity}
   - simple = short, direct, easy to answer in one word or choice
   - intermediate = requires the prospect to think and reflect
   - expert = precise, strategic, requires domain knowledge
5. Tone: ${tone}
6. Allowed types: text | textarea | select | radio | email | url | number
7. Types "select" and "radio" MUST include an "options" array with 2-5 mutually exclusive choices (max 5 words each).
8. Use "text" for short free answers. Use "textarea" only for open-ended deep reflection.
9. Do NOT ask for information already collected in the static answers.
10. Do NOT use "section" type — it is not allowed here.
</rules>

<output_format>
Output ONLY valid raw JSON. No markdown fences. No preamble. No explanation. Just the JSON object.

{
  "questions": [
    { "id": "dq1", "type": "text",     "label": "Question in ${language}?",    "placeholder": "Short hint...",  "required": true  },
    { "id": "dq2", "type": "select",   "label": "Choice question?",             "options": ["A", "B", "C"],       "required": true  },
    { "id": "dq3", "type": "textarea", "label": "Open reflection question?",    "placeholder": "Describe...",    "required": false }
  ]
}
</output_format>

<context>
Form: "${formTitle}"
${extraCtx ? 'Consultant context: ' + extraCtx + '\n' : ''}
Prospect answers collected so far:
${answersBlock}

Objective: generate exactly ${nbQuestions} high-value follow-up questions.
</context>`;

return [{
  json: {
    ...$input.first().json,
    generated_prompt: prompt,
    _meta: { nbQuestions, language, agentActive }
  }
}];

const response = $input.first().json;
let content = response.text || response.message?.content || JSON.stringify(response);

// Strip thinking tags and markdown fences
content = content.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim();
const fenceStart = content.indexOf('```');
if (fenceStart !== -1) {
  const fenceEnd = content.lastIndexOf('```');
  if (fenceEnd > fenceStart) {
    const afterFirstLine = content.indexOf('\n', fenceStart);
    content = content.substring(afterFirstLine > -1 ? afterFirstLine + 1 : fenceStart + 3, fenceEnd).trim();
  }
}

const s = content.indexOf('{'); const e = content.lastIndexOf('}');
let parsed;
try {
  parsed = JSON.parse(s !== -1 && e > s ? content.substring(s, e + 1) : content);
} catch(err) {
  throw new Error('PARSE_FAILED: Gemini returned invalid JSON. Raw: ' + content.substring(0, 300));
}

if (!Array.isArray(parsed.questions) || parsed.questions.length === 0) {
  throw new Error('SCHEMA_ERROR: questions array missing or empty');
}

const ALLOWED = ['text','textarea','select','radio','email','url','number'];
const questions = parsed.questions.map((q, i) => {
  const type = ALLOWED.includes(q.type) ? q.type : 'text';
  const base = {
    id: q.id || ('dq' + (i + 1)),
    type,
    label: q.label || ('Question ' + (i + 1)),
    placeholder: q.placeholder || '',
    required: q.required !== false
  };
  if (['select','radio'].includes(type)) {
    base.options = Array.isArray(q.options) && q.options.length > 0 ? q.options : ['Option A', 'Option B'];
  }
  return base;
});

return [{ json: { questions } }];
